  2: { voo: 1700, bandeja: 1300, intervaloLancar: 3400, aberto: 2000, chanceDefender: 0.5, esperaMax: 3000 },
  3: { voo: 1300, bandeja: 1000, intervaloLancar: 2700, aberto: 1500, chanceDefender: 0.6, esperaMax: 4000 },
}

