  const defesa = painel(s, 167, 404, 306, 68, true)
  defesa.getAt(1).setInteractive({ useHandCursor: true }).setData('bloquearLancamento', true)
    .on('pointerdown', p => { s.comandosDefesa.add(p.id); s.defender() })
