        nomeDefesa.setText(protegendo ? 'Bandeja erguida!' : 'Adulto · defender')
        dicaDefesa.setText(protegendo ? 'Solte para a criança lançar' : 'Segure a bandeja ou Espaço')
        ultimaDefesa = estadoDefesa
      }
    },
  }
}

